import type { HistoryActivity, HistoryBlock, HistoryChapter, HistoryChoice, HistoryLesson, HistoryQuizQuestion, HistorySource, HistoryStep, HistoryTerm, HistoryVisual } from "./kanab-quest-school-history-types";

const sid = (key: string) => "health-lesson-" + key;
const tid = (key: string) => "health-term-" + key;
const lid = (ch: string, n: number) => "health-" + ch + "-" + n;
function source(key: string, title: string, author: string, organization: string, published: string, url: string, passage: string, access: HistorySource["access"], limitation: string): HistorySource {
  return { id: sid(key), title, author, organization, published, url, passage, access, limitation, verifiedAt: "2026-11-12", documentKind: access === "excerpt" ? "Extraits de la publication originale consultés" : "Publication originale scientifique ou institutionnelle" };
}
