const sourceMap = new Map(HEALTH_LESSON_SOURCES.map(s => [s.id, s]));
const refs = (...keys: string[]) => keys.map(key => { const value = sourceMap.get(sid(key)); if (!value) throw new Error("Unknown health source " + key); return value; });
const b = (text: string, evidence: HistoryBlock["evidence"], ...keys: string[]): HistoryBlock => ({ text, evidence, sourceIds: keys.map(sid) });
type Row = readonly [string, string, boolean, string];
const choices = (rows: readonly Row[]): readonly HistoryChoice[] => rows.map(([id, text, correct, feedback]) => ({ id, text, correct, feedback }));
function step(id: string, prompt: string, rows: readonly Row[], reasons: readonly Row[], ...keys: string[]): HistoryStep { return { id, prompt, choices: choices(rows), reasonPrompt: "Quelle raison soutient votre réponse ?", reasons: choices(reasons), sourceIds: keys.map(sid) }; }
function act(ch: string, n: number | "checkpoint", kind: HistoryActivity["kind"], title: string, scenario: string, s: HistoryStep, takeaway: string, fictional = true): HistoryActivity { return { id: n === "checkpoint" ? "health-" + ch + "-checkpoint" : "health-" + ch + "-activity-" + n, kind, title, scenario, fictional, evaluates: s.prompt, steps: [s], takeaway }; }
function visual(title: string, nodes: readonly (readonly [string, string])[], caption: string, ...keys: string[]): HistoryVisual { return { kind: "evidence", title, nodes: nodes.map(([label, detail]) => ({ label, detail })), caption, sourceIds: keys.map(sid) }; }
type Draft = Omit<HistoryLesson, "id" | "minutes" | "glossaryIds" | "relatedLessonIds"> & { glossary: readonly string[] };
function lesson(ch: string, n: number, draft: Draft): HistoryLesson { const { glossary, ...rest } = draft; return { ...rest, id: lid(ch, n), minutes: 4, glossaryIds: glossary.map(tid), relatedLessonIds: [lid(ch, n === 1 ? 2 : 1)] }; }

const observationLessons: readonly HistoryLesson[] = [
  lesson("observation", 1, {
    title: "Décrire avant de nommer", question: "Que montre réellement cette photographie ?", objective: "Séparer observation, indice et hypothèse de cause.",
    essential: [b("Une feuille jaune décrit un changement d’apparence ; elle ne nomme pas sa cause. On peut préciser les zones touchées, les nervures, les bords, l’âge apparent des feuilles et la présence de ponctuations. Un symptôme est une réaction de la plante. Un signe peut correspondre à l’organisme ou à une trace de son activité, comme un mycélium identifié ou des déjections. Une simple tache floue ne suffit pas à établir cette identité.", "observation", "diagnosis"), b("L’enquête commence par ce qui est visible et par ce qui manque. Une photographie documentée d’un cas confirmé enseigne un aspect possible ; une autre plante ressemblante n’hérite pas automatiquement du diagnostic. Le cadrage, la netteté et la légende comptent. Les situations du parcours concernent un chanvre autorisé et restent des exercices : aucune image ne constitue une ordonnance ou une autorisation de traitement.", "interpretation", "sampling", "diagnosis")],
    example: b("Dans le dossier fictif, la légende initiale dit carence certaine. L’image montre seulement plusieurs zones jaunies. Le lecteur corrige en jaunissement visible, cause non confirmée, puis demande des informations complémentaires.", "fiction", "diagnosis"),
    deeper: [b("Décrire n’est pas minimiser le problème. Une description précise rend les comparaisons possibles et empêche de chercher uniquement les éléments qui confirment une intuition. Le mot chlorose décrit un jaunissement lié à une perte de coloration verte ; nécrose désigne un tissu mort. Ces termes ne disent pas quel agent ou quel facteur les a produits. La couleur de l’image peut aussi dépendre de l’éclairage. On conserve donc le document original, son contexte et ses limites, au lieu de transformer une ressemblance avec un atlas en certitude sur le cas étudié.", "interpretation", "diagnosis", "sampling")],
    visual: visual("Trois niveaux à séparer", [["Visible", "Zones jaunes et distribution dans l’image"], ["Hypothèses", "Causes compatibles à examiner"], ["Conclusion", "Diagnostic non confirmé à ce stade"]], "Une légende de référence ne diagnostique pas automatiquement une nouvelle plante.", "diagnosis"),
    activity: act("observation", 1, "dossier", "Examiner les photographies documentées", "Les figures réelles de Punja 2019 associent photographies de brunissements, dépôts blancs, microscopie et identifications décrites dans la publication. La figure 5 compare plusieurs champignons ; l’identité de l’oïdium reste provisoire dans le texte de 2019. Il faut distinguer ces cas étudiés d’une nouvelle plante qui leur ressemblerait.", step("photo", "Quelle lecture distingue correctement aspect et preuve d’identité ?", [["a", "Décrire l’aspect, attribuer l’identité à l’étude, et garder un nouveau cas ressemblant non confirmé.", true, "La publication apporte des éléments qui ne sont pas automatiquement présents dans une nouvelle photographie."], ["b", "Nommer Botrytis sur toute nouvelle plante brunie parce qu’une figure le montre.", false, "La figure 5 illustre justement des brunissements associés à plusieurs champignons étudiés."], ["c", "Transformer tout dépôt blanc en identification d’espèce certaine et actuelle.", false, "L’aspect ne suffit pas, et l’article précise une limite taxonomique pour l’oïdium de 2019."]], [["a", "L’identité attribuée au cas publié repose sur son dossier, pas sur la seule ressemblance visuelle.", true, "Le diagnostic d’une nouvelle plante exige ses propres observations et confirmations."], ["b", "Une photographie de référence transmet automatiquement son diagnostic à toute image similaire.", false, "La ressemblance ne remplace pas les preuves propres au nouveau cas."]], "punja2019", "diagnosis", "sampling"), "Décrire l’image et lire la source sans diagnostiquer une nouvelle plante par ressemblance.", false), glossary: ["symptom", "sign", "chlorosis"], nextQuestion: "Quelle observation supplémentaire ferait vraiment avancer l’enquête ?",
  }),
  lesson("observation", 2, {
    title: "Demander le bon complément", question: "Faut-il une autre photo ou une autre information ?", objective: "Choisir une observation qui permet de départager les hypothèses.",
    essential: [b("Une vue rapprochée renseigne un détail ; une vue d’ensemble montre la répartition sur la plante et autour d’elle. Les deux répondent à des questions différentes. L’envers des feuilles, les tiges et l’état des racines peuvent apporter des indices absents du premier cadrage. L’historique précise quand le changement a été remarqué, comment il évolue et quels événements l’ont précédé. La première date d’observation n’est pas forcément le début du problème.", "observation", "diagnosis", "sampling"), b("Une information est utile si elle peut modifier la comparaison des causes. Demander uniquement une photo plus jolie ou le nom commercial de la variété n’éclaire pas toujours le mécanisme. Pour une analyse, le laboratoire compétent indique les éléments appropriés et leurs conditions de réception. Le cours apprend à préparer les questions ; il ne fournit pas de protocole de prélèvement ou d’expédition de matériel végétal.", "interpretation", "sampling")],
    example: b("Sous abri, plusieurs plants fictifs du même bac flétrissent, tandis qu’un bac voisin paraît normal. L’examen complémentaire révèle des racines brunies, un support humide et un défaut de drainage antérieur. Ces indices soutiennent une piste racinaire sans confirmer à eux seuls une cause infectieuse.", "fiction", "abiotic", "diagnosis", "punja2019"),
    deeper: [b("Un bon dossier relie les images à des dates, à des organes et à des plantes identifiables. Il distingue ce qui a été examiné de ce qui n’a pas été regardé. Dire aucun organisme vu sur cette face est plus précis que aucun ravageur présent. Les photographies de plantes voisines ou d’organes sans signe apparent permettent des comparaisons. L’objectif n’est pas d’accumuler des documents identiques : il est de chercher le renseignement qui manque, puis de reconnaître quand l’identification nécessite une expertise ou une analyse adaptée.", "interpretation", "diagnosis", "sampling")],
    visual: visual("Du détail au contexte", [["Détail", "Face observée, netteté, échelle"], ["Ensemble", "Organes et plantes concernés"], ["Temps", "Début remarqué et évolution"], ["Expertise", "Question et analyse adaptées"]], "Une absence dans le cadrage n’est pas une absence dans toute la plante.", "sampling", "diagnosis"),
    activity: act("observation", 2, "choice", "Choisir l’observation suivante", "Chanvre fictif autorisé sous abri : plusieurs plants d’un même bac flétrissent, le bac voisin paraît normal. Les indices demandés peuvent documenter racines brunies, support humide et défaut de drainage antérieur ; aucune analyse d’agent n’a été faite.", step("additional", "Quelle conclusion respecte ces observations complémentaires ?", [["a", "Les racines brunes confirment une espèce pathogène précise.", false, "La couleur et le flétrissement ne distinguent pas seuls asphyxie, infection ou combinaison de facteurs."], ["b", "Un problème racinaire est plausible ; asphyxie et affection infectieuse restent à départager.", true, "Le contexte et le drainage orientent l’enquête, sans établir une identité d’agent."], ["c", "Le support humide exclut tout problème de fonctionnement des racines.", false, "La présence d’eau ne démontre pas que les racines fonctionnent normalement."]], [["a", "Les nouveaux indices éclairent les mécanismes possibles sans remplacer leur confirmation.", true, "L’état du support, les racines et la chronologie doivent être interprétés ensemble."], ["b", "Un défaut de drainage rend impossible toute infection associée.", false, "Un facteur abiotique et un agent biologique peuvent coexister."]], "diagnosis", "sampling", "abiotic", "punja2019"), "Chercher des indices discriminants et conserver le diagnostic non confirmé."), glossary: ["context", "distribution", "differential"], nextQuestion: "Comment distinguer une cause biologique d’un trouble du milieu ?",
  }),
];

const causeLessons: readonly HistoryLesson[] = [
  lesson("causes", 1, {
    title: "Biotique, abiotique… ou les deux", question: "Une feuille abîmée implique-t-elle un organisme nuisible ?", objective: "Garder plusieurs familles de causes sans appliquer de règle absolue.",
    essential: [b("Une cause biotique implique un agent biologique, par exemple un ravageur ou un agent pathogène. Un trouble abiotique provient d’un facteur non infectieux : dommage mécanique, déséquilibre nutritionnel, stress lié à l’eau ou à la température. Les effets visibles peuvent se ressembler. Une déformation, une chlorose ou un flétrissement ne suffisent donc pas à ranger définitivement le problème dans une seule famille.", "observation", "abiotic", "diagnosis"), b("La répartition et la chronologie orientent l’enquête. Un motif lié à une zone du terrain peut évoquer un facteur du milieu ; une extension progressive peut évoquer une transmission. Ce sont des indices, avec des exceptions. Un organisme peut aussi profiter d’un tissu déjà fragilisé. Causes abiotiques et biologiques peuvent coexister : trouver un insecte ne dispense pas d’examiner les racines, l’environnement et l’histoire de la plante.", "interpretation", "diagnosis", "punja2019")],
    example: b("Après un événement mécanique fictif, plusieurs tiges sont endommagées dans une même bande. Cette répartition soutient une piste physique, mais ne prouve pas que tout autre facteur soit absent.", "fiction", "abiotic"),
    deeper: [b("Les schémas de répartition servent à poser des questions, pas à rendre des verdicts : certains agents touchent plusieurs espèces et certains troubles du milieu restent localisés. Une photographie de feuille ne suffit pas à distinguer un manque d’élément nutritif d’une absorption perturbée par des racines ou un milieu dégradés. L’historique, l’examen racinaire et des analyses adaptées à la question peuvent départager ces pistes, sans déduire un programme d’engrais d’une couleur. Une observation tardive peut aussi faire croire à une apparition soudaine. On sépare donc événement constaté, date de découverte et mécanisme proposé. Si plusieurs facteurs restent compatibles, une explication multifactorielle doit rester ouverte.", "interpretation", "diagnosis", "abiotic")],
    visual: visual("Deux familles, des interactions", [["Abiotique", "Milieu, nutrition, eau, dommage physique"], ["Biotique", "Agent biologique à identifier"], ["Interaction", "Fragilisation et colonisation possibles"]], "La répartition aide à enquêter ; elle n’est pas une signature infaillible.", "diagnosis", "abiotic"),
    activity: act("causes", 1, "matching", "Classer une cause, pas une couleur", "Le dossier fictif documente une tige cassée par un passage mécanique ; aucun agent infectieux n’est établi.", step("families", "Comment classer le mécanisme directement documenté ?", [["a", "Une infection confirmée par la seule cassure.", false, "La cassure montre ici une action mécanique documentée."], ["b", "Une preuve de virus présent dans toutes les plantes voisines.", false, "Aucun résultat ne documente un virus ou les plantes voisines."], ["c", "Un dommage abiotique, sans exclure un problème ultérieur distinct.", true, "Le mécanisme connu est physique ; la suite doit rester observable."]], [["a", "La classification suit le mécanisme étayé plutôt que l’aspect seul.", true, "Une lésion peut avoir différentes origines."], ["b", "Tout tissu abîmé contient nécessairement le même pathogène.", false, "Un dommage ne suffit pas à établir une infection."]], "abiotic", "diagnosis"), "Distinguer la cause établie des possibilités encore ouvertes."), glossary: ["biotic", "abiotic", "necrosis"], nextQuestion: "Comment comparer plusieurs explications d’un même symptôme ?",
  }),
  lesson("causes", 2, {
    title: "Construire le diagnostic différentiel", question: "Une plante flétrie manque-t-elle toujours d’eau ?", objective: "Associer chaque hypothèse à l’information qui pourrait la soutenir ou l’affaiblir.",
    essential: [b("Le flétrissement indique une perte de tenue liée à l’état hydrique des tissus ; il ne dit pas pourquoi elle se produit. Un manque d’eau, un fonctionnement racinaire perturbé ou certains agents pathogènes peuvent conduire à des signes proches. Une mesure pertinente du milieu et des observations de la plante complètent donc l’image. Ajouter une intervention au hasard peut masquer les indices ou aggraver une cause mal comprise.", "interpretation", "diagnosis", "abiotic"), b("Le diagnostic différentiel compare plusieurs hypothèses. Pour chacune, on note les indices compatibles, ceux qui manquent et ceux qui la contredisent. Détecter un organisme n’établit pas automatiquement qu’il explique tout le dépérissement. Dans l’étude de Punja, certaines identifications sont accompagnées de tests de pathogénicité ; d’autres associations restent à confirmer. Le niveau de preuve doit rester attaché à l’agent et au résultat étudiés.", "observation", "punja2019")],
    example: b("Une plante fictive flétrit ; l’état du milieu racinaire et l’historique sont absents. Le dossier conserve plusieurs causes et demande ces informations au lieu de conclure sécheresse ou infection certaine.", "fiction", "diagnosis", "abiotic"),
    deeper: [b("Une hypothèse utile est réfutable : elle prévoit un élément que l’on pourrait observer ou ne pas retrouver. Si le dossier montre un agent dans un tissu, il faut encore considérer sa localisation, la cohérence des lésions et les connaissances disponibles sur cet hôte. Une colonisation secondaire n’a pas la même signification qu’une cause initiale démontrée. L’enquête peut finir provisoirement par diagnostic non confirmé. Cette réponse est rigoureuse lorsqu’elle indique les preuves manquantes et la prochaine vérification, au lieu de choisir arbitrairement le nom le plus connu.", "interpretation", "punja2019", "diagnosis")],
    visual: visual("Comparer les hypothèses", [["Hypothèse", "Mécanisme possible"], ["Pour", "Indices compatibles"], ["Contre ou manque", "Ce qui limite la conclusion"], ["Suite", "Observation ou expertise utile"]], "La présence d’un organisme et la causalité sont deux conclusions différentes.", "punja2019", "diagnosis"),
    activity: act("causes", 2, "dossier", "Départager les hypothèses", "Une plante fictive est flétrie. Pas de mesure pertinente du milieu racinaire, pas d’historique et pas d’identification d’agent.", step("hypotheses", "Quelle conclusion est justifiée ?", [["a", "Un déficit hydrique précis est confirmé.", false, "Le fonctionnement racinaire et le milieu ne sont pas documentés."], ["b", "Diagnostic non confirmé ; examiner milieu, racines et évolution.", true, "Cette réponse garde plusieurs mécanismes et précise la suite utile."], ["c", "Une pourriture infectieuse est confirmée par le flétrissement.", false, "Le symptôme n’identifie pas une infection ni son agent."]], [["a", "Plusieurs mécanismes peuvent produire le même signe visible.", true, "Il faut des indices discriminants avant de privilégier une cause."], ["b", "Le premier nom proposé est le plus fiable.", false, "L’ordre des suppositions ne remplace pas leur confrontation aux données."]], "diagnosis", "abiotic", "punja2019"), "Une incertitude expliquée vaut mieux qu’un diagnostic inventé."), glossary: ["differential", "causality", "pathogenicity"], nextQuestion: "Quels indices permettent d’étudier les arthropodes présents ?",
  }),
];

const pestLessons: readonly HistoryLesson[] = [
  lesson("pests", 1, {
    title: "Qui se trouve sur la plante ?", question: "Tout petit animal observé est-il un ravageur ?", objective: "Distinguer identité, stade de développement et rôle possible.",
    essential: [b("Les arthropodes comprennent notamment insectes et acariens. Ils n’ont pas tous la même biologie ni le même rôle. Certains consomment des tissus végétaux, d’autres se nourrissent de proies ; d’autres encore ne font que passer. Une silhouette imprécise ne suffit pas à décider. L’identification peut demander des caractères fins et tient compte du stade : une larve ne ressemble pas forcément à l’adulte de la même espèce.", "observation", "allies", "mites"), b("Sur chanvre, les ponctuations associées à Tetranychus urticae, un acarien, illustrent une relation entre alimentation sur les feuilles et dégâts visibles. Mais la couleur ou les ponctuations seules ne confirment pas son identité. La fiche NC State associe observations de l’organisme, stades et dégâts. Elle rappelle aussi que les connaissances de gestion obtenues sur d’autres cultures ne se transfèrent pas automatiquement au chanvre.", "observation", "mites")],
    example: b("Le dossier fictif montre un animal minuscule mais ses caractères ne sont pas lisibles. La réponse reste arthropode non identifié, avec besoin d’observation adaptée ; elle n’invente ni espèce ni régime alimentaire.", "fiction", "sampling", "allies"),
    deeper: [b("Compter des pattes sur une image douteuse peut tromper : certaines peuvent être cachées, et les stades diffèrent. La larve du tétranyque décrite par NC State possède six pattes, tandis que les stades suivants en possèdent huit. Ce détail n’est donc pas une clé universelle séparant insectes et acariens sur toute photographie. On confronte plusieurs caractères à une référence fiable. La localisation, les traces d’alimentation et les organismes voisins complètent le dossier, sans transformer automatiquement la proximité avec une lésion en preuve de responsabilité.", "interpretation", "mites", "diagnosis")],
    visual: visual("Identifier avant d’attribuer un rôle", [["Identité", "Caractères lisibles et référence"], ["Stade", "Œuf, larve, nymphe ou adulte selon le groupe"], ["Activité", "Alimentation ou trace documentée"], ["Impact", "Dégâts reliés à cette activité"]], "La présence près d’une lésion n’est pas une preuve suffisante de causalité.", "mites", "allies"),
    activity: act("pests", 1, "choice", "La silhouette insuffisante", "Sur la photo fictive, un petit arthropode est visible mais les caractères d’identification sont flous.", step("identity", "Quelle réponse est la plus solide ?", [["a", "Nommer l’espèce à partir de sa seule petite taille.", false, "Des organismes très différents peuvent avoir une taille proche."], ["b", "Le classer ravageur parce qu’il est sur une feuille.", false, "Des prédateurs et visiteurs sont aussi présents sur les plantes."], ["c", "Conserver l’identité indéterminée et rechercher des caractères adaptés.", true, "La conclusion correspond à la qualité réelle de l’observation."]], [["a", "L’identité et le rôle demandent des preuves distinctes de la simple présence.", true, "Il faut éviter de détruire un auxiliaire ou de manquer un ravageur."], ["b", "Tous les petits arthropodes ont le même régime alimentaire.", false, "Leurs rôles trophiques sont variés."]], "sampling", "allies", "mites"), "Une taille ou une couleur ne remplace pas une identification."), glossary: ["arthropod", "mite", "stage", "pest"], nextQuestion: "Une présence identifiée impose-t-elle toujours une intervention ?",
  }),
  lesson("pests", 2, {
    title: "Présence, pression et dégâts", question: "Un organisme trouvé signifie-t-il une perte importante ?", objective: "Relier observation, évolution et impact sans inventer de seuil.",
    essential: [b("Présence signifie qu’un organisme a été observé ou détecté. La pression décrit notamment son abondance et son évolution dans un contexte donné. Les dégâts décrivent les effets sur la plante ; la perte dépend ensuite de la fonction recherchée. Ces notions ne sont pas interchangeables. Un individu trouvé ne chiffre pas une perte, et une feuille très atteinte ne représente pas nécessairement tout un lot.", "interpretation", "diagnosis", "allies"), b("Une surveillance comparable précise où, quand et sur quoi portent les observations. Compter des feuilles concernées n’est pas compter des animaux, ni mesurer la proportion de surface détruite. Les seuils de décision doivent être étayés pour le couple culture, organisme et contexte. La fiche NC State de 2020 ne proposait pas de seuil de préoccupation validé pour le tétranyque sur chanvre : le cours ne comble pas cette lacune par un chiffre inventé.", "observation", "mites")],
    example: b("Dans un relevé entièrement fictif, trois feuilles examinées portent un organisme identifié. Sans connaître le nombre total observé, la méthode et les dégâts, on ne peut pas qualifier l’ensemble de la parcelle ni décider d’un traitement.", "fiction", "diagnosis"),
    deeper: [b("Le même organisme peut avoir des conséquences différentes selon l’organe touché, l’état de la plante, le stade et le débouché. Une observation ciblée sur la zone la plus abîmée ne fournit pas une estimation représentative de tout le site. Il faut conserver le dénominateur et distinguer absence constatée de recherche non effectuée. La surveillance peut montrer une progression, une stabilité ou une diminution. Ces résultats, avec la présence d’auxiliaires et les connaissances disponibles, aident à justifier une décision proportionnée ; ils ne déclenchent pas automatiquement une intervention universelle.", "interpretation", "diagnosis", "allies", "ipm")],
    visual: visual("Quatre questions différentes", [["Présence", "L’organisme est-il identifié ici ?"], ["Pression", "Quelle abondance et quelle évolution ?"], ["Dégâts", "Quels organes et quelle étendue ?"], ["Décision", "Quel enjeu et quelles preuves ?"]], "Un comptage et un seuil validé ne sont pas la même chose.", "mites", "ipm"),
    activity: act("pests", 2, "dossier", "Un comptage sans dénominateur", "Un relevé fictif annonce trois feuilles concernées, sans nombre total, localisation ni évolution.", step("pressure", "Que peut-on conclure ?", [["a", "L’étendue du problème reste insuffisamment décrite.", true, "Le dénominateur et la méthode manquent pour interpréter la fréquence."], ["b", "Trois feuilles représentent toujours le même niveau de risque.", false, "Trois sur quatre et trois sur plusieurs centaines ne décrivent pas la même fréquence."], ["c", "Le relevé suffit à imposer un produit déterminé.", false, "L’impact, le contexte et les conditions réglementaires restent inconnus."]], [["a", "Une quantité doit être reliée à ce qui a réellement été observé.", true, "La méthode donne sa portée au nombre."], ["b", "Le nombre remplace l’identification et l’état des plantes.", false, "Ces informations répondent à des questions complémentaires."]], "diagnosis", "mites", "ipm"), "Conserver le dénominateur, la méthode et le contexte."), glossary: ["pressure", "incidence", "severity", "threshold"], nextQuestion: "Les agents des maladies appartiennent-ils tous au même groupe ?",
  }),
];

const pathogenLessons: readonly HistoryLesson[] = [
  lesson("pathogens", 1, {
    title: "Des agents différents derrière des dégâts proches", question: "Une pourriture désigne-t-elle un champignon précis ?", objective: "Distinguer champignons, oomycètes et symptômes communs.",
    essential: [b("Pourriture décrit une altération des tissus ; ce mot ne désigne pas une espèce. Botrytis et Fusarium sont des champignons. Pythium, dans les noms utilisés par les études citées, appartient aux oomycètes : ces organismes peuvent ressembler aux champignons par leur croissance filamenteuse, mais forment un groupe distinct. Cette différence biologique compte pour interpréter une identification et les connaissances sur la protection des plantes.", "observation", "punja2019", "oomycetes"), b("Dans l’étude canadienne de Punja, plusieurs agents sont associés à des tissus racinaires ou aériens altérés. Tous les organismes isolés ne reçoivent pas le même niveau de preuve causale. Une masse grise compatible avec Botrytis, ou un dépôt blanc compatible avec un oïdium, constitue une piste à examiner. L’identification d’une espèce ne doit pas être inventée à partir d’une couleur ou d’un nom générique de maladie.", "interpretation", "punja2019", "gray-mold")],
    example: b("Le dossier fictif indique pourriture racinaire et demande un nom d’espèce. Sans identification, la bonne réponse reste agent non confirmé : une catégorie de dégât ne suffit pas à choisir Fusarium ou Pythium.", "fiction", "punja2019"),
    deeper: [b("Une observation peut documenter un organisme vivant sur un tissu déjà mort plutôt que la cause initiale du dommage. Les analyses d’identification, les connaissances sur l’hôte et, en recherche, les tests de pathogénicité apportent des niveaux d’information différents. Punja signale explicitement une détection de Pythium catenulatum dont la pathogénicité sur cannabis restait à confirmer dans cette publication. On ne transforme donc pas la liste de microbes isolés en liste de causes toutes démontrées. Les évolutions de nomenclature demandent aussi de conserver le nom et la date de la source.", "observation", "punja2019", "oomycetes")],
    visual: visual("Nommer le bon niveau", [["Dégât", "Pourriture, nécrose, flétrissement"], ["Groupe", "Champignon ou oomycète, si établi"], ["Identité", "Méthode et référence"], ["Causalité", "Preuves propres à l’agent et à l’hôte"]], "L’aspect visible ne remplace pas l’identification ni sa portée.", "punja2019", "oomycetes"),
    activity: act("pathogens", 1, "matching", "Deux groupes à distinguer", "Un document fictif classe Fusarium et Pythium comme deux virus parce qu’ils sont microscopiques.", step("groups", "Quelle correction est fondée ?", [["a", "Tous les organismes microscopiques sont des virus.", false, "La taille ne définit pas le groupe biologique."], ["b", "Fusarium est un champignon ; Pythium est un oomycète.", true, "Leur ressemblance filamenteuse ne supprime pas leur distinction."], ["c", "Pythium est simplement un autre nom de Fusarium.", false, "Il s’agit de groupes et d’identités différents."]], [["a", "La classification repose sur la biologie et la parenté, pas sur la seule visibilité.", true, "Des organismes petits peuvent appartenir à des groupes très différents."], ["b", "Tous les agents responsables d’une pourriture sont identiques.", false, "Des causes différentes peuvent produire des dégâts proches."]], "oomycetes", "punja2019"), "Séparer le nom du dégât du nom de l’agent."), glossary: ["fungus", "oomycete", "mycelium", "pathogen"], nextQuestion: "Comment enquêter lorsque l’agent n’est pas visible sur une photographie ?",
  }),
  lesson("pathogens", 2, {
    title: "Virus, viroïdes et limites des tests", question: "Une plante sans symptôme est-elle nécessairement indemne ?", objective: "Lire une détection ciblée sans la transformer en bilan sanitaire complet.",
    essential: [b("Les virus végétaux et les viroïdes sont des agents distincts. Un viroïde est un petit ARN circulaire qui ne code pas de protéines et n’est pas entouré d’une capside. Il utilise les fonctions de la plante pour se multiplier. Cette définition ne signifie pas organisme autonome hors de son hôte. L’ICTV précise que certaines infections peuvent se produire sans signe apparent ; la photographie ne suffit donc pas à exclure leur présence.", "observation", "viroids"), b("HLVd, le viroïde latent du houblon, a été détecté dans des échantillons de cannabis, y compris chez certaines plantes asymptomatiques de l’étude canadienne citée. Une RT-PCR cible un ARN précis. Un résultat doit être lu avec la cible, l’échantillon, la date et les limites de la méthode. Positif ne chiffre pas à lui seul la gravité ; négatif pour une cible ne signifie pas absence de toute maladie.", "observation", "hlvd", "viroids")],
    example: b("Le laboratoire fictif écrit HLVd non détecté dans cet échantillon. Le lecteur refuse de remplacer cette phrase par plante garantie indemne de tous les virus, viroïdes et champignons.", "fiction", "hlvd", "diagnosis"),
    deeper: [b("Une analyse répond à une question définie. Son interprétation dépend du matériel examiné et de ce que la méthode peut détecter ; elle ne décrit pas automatiquement chaque partie d’une plante ni tous les agents possibles. Une détection peut étayer une infection tout en laissant ouverte la contribution d’autres facteurs aux symptômes. Les échantillons soumis à un laboratoire ne sont pas forcément représentatifs d’une région entière. Le cours distingue ainsi identité de l’agent, présence dans l’échantillon, symptômes et rôle causal, sans fournir de protocole de manipulation ou d’analyse.", "interpretation", "hlvd", "sampling", "punja2019")],
    visual: visual("Lire la portée d’un résultat", [["Cible", "Quel agent recherché ?"], ["Échantillon", "Quel matériel et quelle date ?"], ["Résultat", "Détecté ou non détecté dans ce cadre"], ["Limites", "Pas un certificat universel de santé"]], "Une infection peut être asymptomatique ; un test ciblé reste ciblé.", "hlvd", "viroids"),
    activity: act("pathogens", 2, "dossier", "Le résultat trop élargi", "Un résultat fictif porte sur une seule cible et un seul échantillon. Une affiche annonce ensuite aucun agent pathogène dans toute la plante.", step("test", "Quelle interprétation conserver ?", [["a", "L’affiche est confirmée pour tous les groupes d’agents.", false, "Le test ne recherche pas toutes les causes possibles."], ["b", "Le résultat n’a aucune valeur parce qu’il est ciblé.", false, "Il apporte une information utile sur la question effectivement examinée."], ["c", "La conclusion doit rester limitée à la cible, à l’échantillon et à la méthode.", true, "On conserve l’information sans lui attribuer une portée générale."]], [["a", "Le champ d’une analyse borne le champ de sa conclusion.", true, "Une recherche particulière ne vaut pas inventaire exhaustif."], ["b", "L’absence de symptôme rend tout test superflu.", false, "Certaines infections peuvent rester sans signes apparents."]], "hlvd", "viroids", "sampling"), "Un résultat ciblé informe ; il ne garantit pas tout."), glossary: ["virus", "viroid", "asymptomatic", "targeted-test"], nextQuestion: "Quels organismes peuvent aider à limiter certains ravageurs ?",
  }),
];

const allyLessons: readonly HistoryLesson[] = [
  lesson("allies", 1, {
    title: "Reconnaître les rôles utiles", question: "Une larve peut-elle être un auxiliaire ?", objective: "Distinguer consommateur de plante, prédateur et parasitoïde.",
    essential: [b("Un auxiliaire contribue, dans un contexte donné, à limiter un organisme dommageable. Un prédateur consomme des proies ; un parasitoïde se développe aux dépens d’un hôte qu’il finit généralement par tuer. Ces rôles ne se lisent pas seulement dans la taille ou l’allure. Les fiches de chanvre de Virginia Tech décrivent notamment des coccinelles prédatrices, des larves de chrysopes, des araignées et des parasitoïdes de pucerons.", "observation", "allies"), b("Le stade compte. Une larve prédatrice peut paraître très différente d’un adulte familier ; l’éliminer parce qu’elle ressemble à une petite chenille ferait perdre une interaction utile. Inversement, connaître le nom d’une grande famille ne garantit pas le rôle de chaque espèce. On identifie l’organisme et son activité avant de le classer. Les observations régionales citées documentent des présences ; elles ne garantissent pas un niveau de contrôle dans tout projet.", "interpretation", "allies", "diagnosis")],
    example: b("Le dossier fictif confirme une larve de coccinelle prédatrice consommant des pucerons. Elle est classée auxiliaire dans cette interaction. Cette information ne donne pas un pourcentage garanti de réduction de la population.", "fiction", "allies"),
    deeper: [b("Les pucerons parasités peuvent laisser des formes appelées momies, décrites dans les références entomologiques. Ce signe d’une interaction ne doit pas être confondu avec une preuve que tous les pucerons du site sont maîtrisés. D’autres observations restent nécessaires pour suivre leur évolution. La présence d’un prédateur n’exclut pas non plus un dommage local. Une enquête utile examine simultanément les organismes consommant la plante et leurs ennemis naturels, puis conserve les incertitudes sur l’équilibre réel. Elle évite de donner une valeur morale de bon ou mauvais à tout un groupe animal.", "interpretation", "allies", "ipm")],
    visual: visual("Trois relations", [["Phytophage", "Consomme un tissu végétal"], ["Prédateur", "Consomme des proies"], ["Parasitoïde", "Se développe aux dépens d’un hôte"]], "Le rôle dépend de l’identité, du stade et de l’interaction documentée.", "allies"),
    activity: act("allies", 1, "matching", "Auxiliaire ou ravageur ?", "Dans le dossier fictif, l’identification est confirmée : une larve de coccinelle prédatrice consomme des pucerons ; les pucerons se nourrissent de la plante.", step("roles", "Quel classement respecte cette interaction ?", [["a", "Larve prédatrice auxiliaire ; pucerons phytophages dans ce cas.", true, "Les rôles suivent les activités documentées, sans promettre une maîtrise complète."], ["b", "Toute larve est un ravageur, même lorsqu’elle consomme des pucerons.", false, "Le stade larvaire ne détermine pas à lui seul le régime alimentaire."], ["c", "La présence de la larve prouve que tous les dégâts ont cessé.", false, "Une interaction utile ne mesure pas encore l’impact global."]], [["a", "Le rôle se déduit de l’identité et de l’alimentation observée.", true, "Il ne se décide pas à partir d’une silhouette jugée inquiétante."], ["b", "La taille d’un animal suffit à déterminer son effet sur la plante.", false, "Des organismes de taille proche ont des régimes différents."]], "allies"), "Reconnaître l’interaction avant de classer l’organisme."), glossary: ["auxiliary", "predator", "parasitoid", "phytophagous"], nextQuestion: "Quand une interaction utile devient-elle une efficacité démontrée ?",
  }),
  lesson("allies", 2, {
    title: "Une efficacité à documenter", question: "Un auxiliaire présent garantit-il un résultat ?", objective: "Distinguer mécanisme possible, présence observée et efficacité mesurée.",
    essential: [b("Observer une prédation montre qu’une interaction existe. Démontrer une réduction des dégâts demande une comparaison et des mesures adaptées. L’efficacité peut dépendre de la cible, du stade, de l’environnement et des autres pratiques. Une observation en laboratoire ou un essai dans une serre ne représente pas automatiquement tous les contextes. Le mot auxiliaire n’est donc ni un pourcentage d’efficacité ni une promesse d’absence de risque.", "interpretation", "allies", "mites", "ipm"), b("Cette prudence vaut aussi pour les micro-organismes. Dans Punja 2019, l’inhibition d’un agent sur un milieu de laboratoire ne suffit pas à démontrer qu’un endophyte protège une plante entière. Présence dans un tissu, production d’une substance et bénéfice au champ sont des résultats différents. Une proposition de biocontrôle doit préciser son identité, les preuves, les limites et le cadre applicable, plutôt que s’appuyer sur le seul mot naturel.", "observation", "punja2019", "ephy-mentions")],
    example: b("Une publicité fictive transforme une observation de prédation en garantie universelle. Le lecteur demande une comparaison pertinente, la cible étudiée, les dégâts mesurés et les conditions de l’essai.", "fiction", "allies", "ipm"),
    deeper: [b("Conserver des ennemis naturels déjà présents et introduire un organisme sont deux décisions différentes. La seconde suppose notamment une identité fiable et un cadre approprié ; le cours ne propose ni achat ni lâcher. Les produits phytopharmaceutiques portant une mention de biocontrôle restent liés à des usages et conditions. Leur évaluation n’est pas remplacée par une recette artisanale ou par une preuve obtenue avec un autre organisme. Une méthode utile doit aussi préserver, autant que possible, les interactions favorables et être réévaluée dans le dossier considéré.", "interpretation", "ephy-mentions", "ephy-uses", "ipm")],
    visual: visual("Une échelle de preuves", [["Interaction", "La proie est consommée"], ["Essai", "Résultat comparé dans des conditions définies"], ["Transposition", "Même cible et contexte pertinent ?"], ["Cadre", "Identité et conditions applicables"]], "Un effet au laboratoire ne garantit pas un bénéfice dans tous les milieux.", "punja2019", "allies", "ephy-mentions"),
    activity: act("allies", 2, "documents", "Lire la promesse de biocontrôle", "Une publicité fictive affirme : ce micro-organisme inhibe un champignon sur une boîte de laboratoire, il protège donc tous les chanvres.", step("efficacy", "Quelle réserve est nécessaire ?", [["a", "L’essai de laboratoire démontre déjà toutes les situations de terrain.", false, "La plante, le milieu et les interactions n’y sont pas tous représentés."], ["b", "L’effet observé mérite une étude pertinente sur la plante et la cible.", true, "La preuve est utile, mais sa portée ne doit pas être élargie sans données."], ["c", "Toute observation au laboratoire est sans aucune valeur.", false, "Elle peut documenter un mécanisme ou une piste, sans garantir l’application."]], [["a", "Le niveau de preuve doit correspondre à la conclusion annoncée.", true, "Mécanisme possible et efficacité pratique ne sont pas le même résultat."], ["b", "Le mot naturel supprime les conditions d’efficacité et d’autorisation.", false, "L’origine ne remplace aucune de ces vérifications."]], "punja2019", "ephy-mentions"), "Une piste prometteuse reste une piste tant que la conclusion dépasse l’essai."), glossary: ["biocontrol", "endophyte", "efficacy"], nextQuestion: "Comment réduire les occasions de problème avant les premiers dégâts ?",
  }),
];

const preventionLessons: readonly HistoryLesson[] = [
  lesson("prevention", 1, {
    title: "Comprendre les voies de propagation", question: "Que faut-il surveiller avant de chercher un traitement ?", objective: "Relier prévention, introduction et circulation possibles des agents.",
    essential: [b("La prévention cherche à réduire des occasions d’introduction, de transmission ou de fragilisation. Matériel végétal, équipements, eau et mouvements entre zones peuvent jouer des rôles différents selon l’agent. Dans les travaux de Punja, les sources possibles et la circulation de microorganismes sont étudiées dans des sites définis. Ces observations n’autorisent pas à considérer chaque objet comme contaminé : elles indiquent les voies à documenter.", "observation", "punja2019"), b("La démarche intégrée donne une place à la traçabilité du matériel, à l’hygiène adaptée, à la surveillance et à la protection des organismes utiles. Une mesure préventive doit viser un mécanisme plausible. Nettoyage visuel, désinfection validée et absence de tout agent sont des notions différentes. Le cours n’enseigne pas de préparation de produit : il apprend à demander quel risque est visé et quelle preuve soutient la mesure proposée.", "interpretation", "ipm", "ephy-uses")],
    example: b("Dans une pépinière fictive autorisée, le registre ne relie plus les plantes à leur lot d’origine. Retrouver cette traçabilité aide l’enquête ; l’oubli ne prouve pas en soi une infection.", "fiction", "sampling", "punja2019"),
    deeper: [b("Prévenir n’est pas promettre un espace stérile. Les mesures s’inscrivent dans une organisation : observations consignées, responsabilités connues et information conservée lorsque du matériel change de zone. Une rupture de traçabilité peut compliquer l’identification d’une source sans constituer elle-même un diagnostic. Si un risque de transmission est suspecté, l’évaluation compétente peut justifier des précautions proportionnées pendant la confirmation. Le choix dépend de l’agent envisagé et du contexte ; il ne consiste pas à appliquer indistinctement le même produit à toutes les plantes ou à toutes les surfaces.", "interpretation", "ipm", "diagnosis", "punja2019")],
    visual: visual("Documenter les circulations", [["Entrée", "Origine et état du matériel"], ["Mouvements", "Zones, objets et contacts"], ["Suivi", "Dates et observations reliées"], ["Mesure", "Risque visé et portée démontrée"]], "Une voie possible n’est pas la preuve d’une contamination réelle.", "punja2019", "ipm"),
    activity: act("prevention", 1, "dossier", "Le registre incomplet", "Dans le cas fictif, des plantes présentent des signes différents mais le lien avec leur lot d’origine a disparu.", step("trace", "Quelle démarche améliore l’enquête ?", [["a", "Déclarer tous les lots infectés par le même agent.", false, "Le manque de traçabilité ne fournit pas ce diagnostic."], ["b", "Ignorer les origines parce qu’une photo existe.", false, "La photo ne remplace pas l’historique des mouvements et des lots."], ["c", "Reconstituer les origines et observations, en conservant les inconnues.", true, "Ces données peuvent éclairer les voies plausibles et les comparaisons."]], [["a", "La traçabilité relie les faits sans transformer une lacune en certitude.", true, "Une donnée absente doit rester signalée comme telle."], ["b", "Une origine inconnue prouve nécessairement un agent précis.", false, "L’identité de l’agent nécessite ses propres preuves."]], "sampling", "punja2019", "ipm"), "La prévention commence aussi par des informations fiables."), glossary: ["prevention", "transmission", "traceability", "hygiene"], nextQuestion: "Comment le milieu change-t-il la probabilité d’une maladie ?",
  }),
  lesson("prevention", 2, {
    title: "Le milieu fait partie de l’enquête", question: "Une atmosphère humide suffit-elle à diagnostiquer une maladie ?", objective: "Distinguer condition favorable, exposition et maladie effective.",
    essential: [b("Une maladie infectieuse dépend de l’agent, d’un hôte sensible et de conditions permettant l’interaction. Une condition favorable n’est donc pas un diagnostic. NC State décrit des situations fraîches et humides favorisant la pourriture grise ; cela ne signifie pas que toute plante humide porte Botrytis. D’autres organismes ont des relations différentes au milieu : le tétranyque cité n’a pas les mêmes conditions favorables que cette moisissure.", "observation", "gray-mold", "mites", "diagnosis"), b("L’enquête décrit le lieu de la mesure, les surfaces, l’état des racines et l’évolution. Un chiffre mesuré au centre d’un abri ne représente pas nécessairement chaque zone. La botanique des racines, le chapitre sur les causes et les leçons sur l’humidité complètent ces questions. Il faut considérer les interactions entre facteurs plutôt que chercher un réglage universel qui supprimerait tous les risques. Le présent cours ne propose aucune consigne climatique de production.", "interpretation", "diagnosis", "abiotic")],
    example: b("Une serre fictive présente de la condensation. Le dossier retient un indice physique et recherche d’autres observations ; il n’annonce ni une espèce de champignon ni une contamination de tous les produits.", "fiction", "gray-mold", "diagnosis"),
    deeper: [b("Modifier un facteur peut influencer plusieurs organismes et plusieurs fonctions de la plante. C’est pourquoi une recommandation générale sans identification ni contexte peut déplacer le problème au lieu de le résoudre. Le raisonnement reste : quel mécanisme est compatible avec les observations, quelle mesure est pertinente pour le vérifier et quelles conséquences faut-il considérer ? Les documents régionaux décrivent des situations utiles, mais leurs fréquences et conseils ne s’appliquent pas automatiquement ailleurs. Une mesure professionnelle éventuelle doit être adaptée au cas autorisé, avec ses objectifs et ses limites clairement annoncés.", "interpretation", "diagnosis", "gray-mold", "mites")],
    visual: visual("Une interaction à documenter", [["Agent", "Présence et identité"], ["Hôte", "Plante et sensibilité étudiée"], ["Milieu", "Conditions réellement observées"], ["Temps", "Évolution de l’interaction"]], "Un facteur favorable ne démontre pas à lui seul une maladie.", "diagnosis", "gray-mold"),
    activity: act("prevention", 2, "choice", "L’humidité devenue diagnostic", "Un rapport fictif conclut Botrytis confirmé parce qu’un abri était humide ; aucune observation de tissu ou d’agent n’est fournie.", step("environment", "Quelle correction faut-il apporter ?", [["a", "L’humidité est un contexte possible, mais le diagnostic reste non confirmé.", true, "Le milieu seul ne documente ni agent ni maladie effective."], ["b", "L’humidité identifie toujours la même espèce.", false, "Plusieurs phénomènes et organismes peuvent coexister dans ce milieu."], ["c", "Le milieu n’a jamais de rôle dans les maladies.", false, "Il peut favoriser ou limiter des interactions, sans suffire à les prouver."]], [["a", "Condition favorable et preuve de maladie sont deux niveaux différents.", true, "Il faut relier l’agent, l’hôte et les observations."], ["b", "Une mesure centrale remplace l’examen de tous les organes.", false, "Elle ne décrit pas l’état biologique de l’ensemble de la plante."]], "gray-mold", "diagnosis"), "Étudier le milieu sans lui faire dire le nom d’une maladie."), glossary: ["host", "susceptibility", "favourable-condition"], nextQuestion: "Comment ordonner les décisions de protection intégrée ?",
  }),
];

const ipmLessons: readonly HistoryLesson[] = [
  lesson("ipm", 1, {
    title: "Ordonner une réponse proportionnée", question: "La première étape est-elle de choisir un produit ?", objective: "Relier prévention, surveillance, confirmation, choix et réévaluation.",
    essential: [b("La protection intégrée commence avant un problème par la prévention et la surveillance. Lorsqu’un indice apparaît, on décrit, on cherche les éléments qui départagent les causes et on fait confirmer ce qui doit l’être. La décision considère ensuite l’évolution, les dégâts et l’enjeu. Une intervention n’est pas automatique à la première présence ; attendre passivement n’est pas non plus une règle universelle lorsqu’un risque documenté appelle une réponse compétente.", "interpretation", "ipm", "diagnosis"), b("Les mesures culturales, physiques ou biologiques pertinentes sont examinées avant de réduire la décision à un produit. Leur efficacité, leurs effets non ciblés et leurs contraintes comptent. Si une mesure réglementée est envisagée, les conditions applicables se vérifient avant l’action. Le résultat est ensuite suivi. Cet ordre est une méthode de décision, pas un programme de traitement : le cours ne fixe ni produit, ni quantité, ni calendrier.", "interpretation", "ipm", "ephy-uses", "allies")],
    example: b("Le dossier fictif propose acheter d’abord, nommer le problème ensuite. Le lecteur réordonne : observer et confirmer, apprécier l’enjeu, comparer les réponses pertinentes, vérifier leur cadre, puis suivre le résultat.", "fiction", "ipm", "diagnosis"),
    deeper: [b("La prévention reste active pendant tout le suivi ; les étapes forment une boucle plutôt qu’une recette rigide. Une confirmation spécialisée et une précaution proportionnée peuvent être conduites en parallèle si le contexte le justifie. Les seuils de décision ne sont pas copiés arbitrairement d’une autre culture. Une méthode non chimique n’est pas automatiquement efficace ou sans effet indésirable ; elle doit aussi être évaluée. Après une décision, conserver les observations permet de vérifier si l’objectif a été atteint et de revoir l’hypothèse lorsque les faits ne correspondent pas aux attentes.", "interpretation", "ipm", "mites", "diagnosis")],
    visual: visual("La boucle de décision", [["Prévenir et surveiller", "Réduire les risques et repérer les changements"], ["Confirmer", "Départager les causes et apprécier l’enjeu"], ["Choisir", "Mesure pertinente et cadre vérifié"], ["Réévaluer", "Observer le résultat et ajuster le raisonnement"]], "La proportionnalité dépend du dossier, pas d’un automatisme de traitement.", "ipm", "diagnosis"),
    activity: act("ipm", 1, "order", "Remettre l’enquête dans l’ordre", "Dans le cas fictif, aucun danger urgent n’est documenté et le diagnostic reste ouvert. Il faut ordonner le raisonnement.", step("order", "Quel enchaînement est cohérent ?", [["a", "Produit choisi → application supposée → recherche d’une cause qui le justifie.", false, "Cette démarche subordonne le diagnostic à une décision déjà prise."], ["b", "Prévention et surveillance → confirmation utile → réponse proportionnée et cadre vérifié → suivi.", true, "La décision découle des preuves et conserve une réévaluation."], ["c", "Photographie unique → espèce certaine → abandon de toute surveillance.", false, "L’image ne garantit pas l’identité et le suivi reste nécessaire."]], [["a", "L’intervention doit répondre au problème étayé et son résultat doit être vérifié.", true, "On évite de confondre achat, diagnostic et réussite."], ["b", "Une méthode dite naturelle dispense de diagnostic.", false, "Son intérêt dépend aussi de la cible et du contexte."]], "ipm", "diagnosis", "ephy-uses"), "Choisir après l’enquête, puis vérifier ce qui s’est réellement passé."), glossary: ["ipm", "proportionality", "monitoring", "non-target"], nextQuestion: "Comment vérifier qu’une autorisation correspond au cas envisagé ?",
  }),
  lesson("ipm", 2, {
    title: "Lire un usage autorisé", question: "Un produit autorisé l’est-il pour toute plante et toute cible ?", objective: "Lire portée, conditions et date sans extrapoler une autorisation.",
    essential: [b("En France, E-Phy présente les produits phytopharmaceutiques et leurs usages. Une autorisation ne se résume pas à un nom commercial. Il faut relier le produit exact, son statut actuel, la culture ou la portée du regroupement, la cible, le mode d’usage et les conditions. Les restrictions peuvent limiter une portée apparemment large. Une autorisation sur une autre culture ou contre un autre organisme ne se transpose pas par analogie.", "law", "ephy-uses"), b("Les mentions biocontrôle et utilisable en agriculture biologique ont des significations réglementaires distinctes ; elles ne veulent pas dire autorisé partout ou sans risque. Un document de recherche étranger ne remplace pas la décision française à jour. Le cours entraîne à lire et à repérer ce qui manque. Il ne nomme pas ici de produit à employer et ne fournit aucun dosage, mélange, fréquence ou mode opératoire.", "law", "ephy-mentions", "ephy-uses")],
    example: b("Une fiche pédagogique fictive ne montre qu’une cible limaces et escargots, alors que le dossier porte sur des thrips. Cette cible affichée ne justifie pas l’usage proposé ; il faut aussi vérifier la culture, la portée, les conditions et l’état actuel.", "fiction", "ephy-uses"),
    deeper: [b("La lecture peut s’arrêter à information insuffisante ou usage non établi pour ce dossier. Ce n’est pas la même conclusion qu’un retrait général du produit. E-Phy distingue également la portée autorisée et les précisions sur les organismes pour lesquels une efficacité a été montrée : l’une ne doit pas être reconstruite à partir de l’autre. La date de consultation, les restrictions et la décision associée sont donc importantes. Avant toute action réelle, le professionnel vérifie le cadre complet ; la réussite de l’exercice ne constitue aucune prescription ni validation d’un cas individuel.", "law", "ephy-uses", "ephy-mentions")],
    visual: visual("Les correspondances à vérifier", [["Produit", "Identité et statut actuels"], ["Usage", "Culture ou portée, cible et mode"], ["Conditions", "Restrictions, gamme et décision"], ["Dossier", "Correspondance établie ou information manquante"]], "Une mention favorable ne remplace pas la lecture de l’usage.", "ephy-uses", "ephy-mentions"),
    activity: act("ipm", 2, "documents", "La fiche correspond-elle au dossier ?", "Extrait fictif d’apprentissage : seul un usage visant limaces et escargots est montré. Le cas concerne des thrips ; culture et conditions complètes ne sont pas renseignées.", step("authorization", "Que peut-on conclure à partir de cet extrait ?", [["a", "L’usage contre les thrips est établi parce que le produit a une autorisation.", false, "L’existence d’une autorisation ne couvre pas toute cible."], ["b", "Le produit est nécessairement interdit pour tous ses usages.", false, "L’extrait ne démontre pas un retrait général."], ["c", "Cet extrait n’établit pas l’usage proposé ; cible, portée et conditions doivent correspondre.", true, "La cible montrée ne correspond pas et le reste du dossier est incomplet."]], [["a", "Une autorisation est liée à des usages et conditions précis.", true, "On ne transpose ni une cible ni une culture par simple ressemblance."], ["b", "Biocontrôle signifie autorisé pour toutes les cultures et tous les organismes.", false, "La mention ne remplace pas les usages autorisés."]], "ephy-uses", "ephy-mentions"), "Lire la correspondance exacte avant toute conclusion d’autorisation."), glossary: ["authorization", "use", "scope", "biocontrol"], nextQuestion: "Comment vérifier la fiabilité d’une promesse de résistance ou de réussite ?",
  }),
];

const verificationLessons: readonly HistoryLesson[] = [
  lesson("verification", 1, {
    title: "Vérifier la portée d’une source", question: "Une histoire variétale prouve-t-elle une résistance ?", objective: "Distinguer réputation, observation et essai comparatif.",
    essential: [b("Une source doit répondre à la question posée. Une fiche historique peut documenter un territoire ou un usage ; elle ne mesure pas automatiquement une résistance. Une observation sur une variété dans un site ne garantit pas son comportement face à tous les agents. Pour examiner une revendication sanitaire, il faut connaître l’identité du matériel, l’agent, les conditions, le comparateur et ce qui a été mesuré.", "interpretation", "diagnosis", "punja2019"), b("Une résistance réduit la sensibilité dans une relation donnée ; une tolérance concerne les conséquences subies malgré l’atteinte. Les deux ne signifient pas immunité universelle. Les noms commerciaux peuvent aussi recouvrir des matériels différents. Le lecteur conserve donc les limites et la date du document, recherche une preuve pertinente et ne transforme pas une réputation de rusticité en dispense de surveillance ou en garantie de sécurité du produit.", "interpretation", "response", "ipm", "diagnosis")],
    example: b("La fiche réelle du Buddy Carmagnola, HH2026-045, présente une histoire piémontaise de semences, fibres et cordages. Ce contenu est attribué à la fiche du jeu. Il ne démontre aucune résistance à Botrytis, à un acarien ou à un viroïde.", "interpretation", "buddy-carmagnola"),
    buddyCodes: ["HH2026-045"],
    deeper: [b("La qualité d’une preuve dépend de son dessin autant que de son titre. Une comparaison devrait distinguer exposition à l’agent, fréquence de l’infection et conséquences mesurées, avec des conditions et répétitions adaptées. Une plante restée saine peut ne pas avoir rencontré l’agent : cela ne prouve pas à elle seule une résistance génétique. Une publication ancienne peut rester utile, mais son absence de données à l’époque ne démontre pas que rien n’a été étudié depuis. L’enquête garde l’attribution exacte et évite les garanties ajoutées par le lecteur.", "interpretation", "diagnosis", "punja2019", "ipm")],
    visual: visual("Quelle preuve pour quelle affirmation ?", [["Histoire", "Origine et usages attribués"], ["Observation", "Ce qui s’est produit dans un contexte"], ["Essai", "Comparateur, agent et critères"], ["Portée", "Ce que les résultats permettent de conclure"]], "Une carte de collection reste lisible sans prouver une propriété sanitaire.", "buddy-carmagnola", "diagnosis"),
    activity: act("verification", 1, "documents", "La promesse ajoutée à la fiche", "Un commentaire fictif ajoute à la fiche historique de Carmagnola : cette ancienneté prouve une résistance à toutes les maladies.", step("source", "Quelle réponse respecte la source réelle ?", [["a", "L’ancienneté démontre une immunité universelle.", false, "Une histoire variétale ne mesure pas une résistance à chaque agent."], ["b", "La fiche documente une histoire ; la résistance demande d’autres preuves.", true, "L’attribution reste fidèle à ce que la fiche décrit."], ["c", "L’absence de test dans la fiche démontre une sensibilité à toutes les maladies.", false, "L’absence de preuve de résistance ne prouve pas l’inverse universel."]], [["a", "Une source ne peut établir une propriété qu’elle n’a pas étudiée.", true, "Le niveau de conclusion doit rester relié au contenu réel."], ["b", "Toute variété ancienne dispense d’observer les plantes.", false, "Le nom et l’ancienneté ne remplacent pas la surveillance."]], "buddy-carmagnola", "diagnosis"), "Ne pas ajouter à la fiche une propriété qu’elle ne démontre pas."), glossary: ["resistance", "tolerance", "comparator", "evidence"], nextQuestion: "Comment reconnaître un résultat utile sans promettre trop ?",
  }),
  lesson("verification", 2, {
    title: "Suivre le résultat et ses limites", question: "Une amélioration visible suffit-elle à tout conclure ?", objective: "Distinguer évolution observée, efficacité et sécurité du produit.",
    essential: [b("Après une décision, on revient aux observations comparables : même objet, méthode cohérente, dates et critères explicites. Une amélioration après une action n’établit pas toujours qu’elle en est la cause. Le milieu, la dynamique des organismes ou d’autres changements peuvent intervenir. Le suivi vérifie la progression des dégâts et les effets inattendus, puis permet de réexaminer une hypothèse qui n’explique pas les résultats.", "interpretation", "ipm", "diagnosis"), b("La santé apparente de la plante et la sécurité d’un produit sont encore deux questions différentes. Une matière moisie ne devient pas déclarée consommable parce que sa surface semble nettoyée. Certaines moisissures peuvent produire des toxines ; la couleur ne permet pas d’en affirmer ou d’en exclure la présence. Le parcours ne propose aucune récupération artisanale : un lot suspect relève d’une évaluation et des règles adaptées à son usage.", "observation", "mycotoxins")],
    example: b("Un dossier fictif annonce succès total après une photo plus verte, sans observation comparable ni contrôle du produit. Le lecteur limite la conclusion à l’amélioration visible et demande ce qui a réellement été suivi.", "fiction", "diagnosis", "ipm"),
    deeper: [b("Pour évaluer une mesure, on distingue son objectif initial de résultats qui n’ont pas été mesurés. Moins d’animaux observés n’implique pas forcément moins de dégâts déjà présents ; moins de moisissure visible ne constitue pas une analyse de toxines. L’OMS indique que les risques liés aux mycotoxines ne se limitent pas toujours à la surface visible et que beaucoup résistent à des transformations alimentaires. Cette information générale ne diagnostique pas un lot précis. Elle justifie de ne pas inventer une garantie de sécurité à partir d’un changement d’aspect.", "interpretation", "mycotoxins", "ipm")],
    visual: visual("Trois conclusions séparées", [["Évolution", "Ce qui a changé dans les observations"], ["Efficacité", "Ce qui peut être attribué à la mesure"], ["Sécurité", "Évaluation propre au produit et à l’usage"]], "Une amélioration d’aspect ne vaut ni preuve causale complète ni garantie de consommabilité.", "ipm", "mycotoxins"),
    activity: act("verification", 2, "dossier", "Corriger le succès total", "Une photo fictive montre moins de matière moisie en surface ; aucun résultat analytique ni évaluation du lot n’est fourni.", step("outcome", "Quelle conclusion reste justifiée ?", [["a", "Le lot est garanti consommable parce que la surface paraît meilleure.", false, "L’aspect ne démontre pas l’absence de contamination ni de toxines."], ["b", "La photo identifie une toxine précise et sa quantité.", false, "Une image ne fournit ni identité chimique ni concentration."], ["c", "L’aspect a changé, mais la sécurité du lot n’est pas établie.", true, "On sépare l’observation de la conclusion sanitaire non documentée."]], [["a", "Les critères de sécurité nécessitent des preuves adaptées, distinctes de l’apparence.", true, "Le parcours n’invente pas de méthode pour rendre consommable un produit suspect."], ["b", "Tout ce qui est invisible a nécessairement disparu.", false, "L’absence visuelle n’est pas une analyse exhaustive."]], "mycotoxins", "diagnosis"), "Conclure sur ce qui est mesuré et conserver les autres questions ouvertes."), glossary: ["followup", "causality", "mycotoxin", "product-safety"], nextQuestion: "Saurez-vous justifier une conclusion sans dépasser les preuves ?",
  }),
];

function checkpoint(ch: string, title: string, scenario: string, prompt: string, rows: readonly Row[], reasons: readonly Row[], keys: readonly string[], takeaway: string): HistoryActivity {
  return act(ch, "checkpoint", "dossier", title, scenario, step("transfer", prompt, rows, reasons, ...keys), takeaway);
}
function chapter(id: string, number: number, title: string, introduction: string, context: HistoryChapter["context"], lessons: readonly HistoryLesson[], checkpoint: HistoryActivity): HistoryChapter {
  return { id, number, title, introduction, context, lessons, checkpoint };
}
