function q(ch: string, n: number, part: number, prompt: string, texts: readonly [string, string, string, string], keys: readonly string[], difficulty: "easy" | "medium" = "medium"): HistoryQuizQuestion {
  return { id: "health-" + ch + "-q" + String(n).padStart(2, "0"), chapterId: ch, lessonId: "biodiversity", sectionId: lid(ch, part), prompt, difficulty, options: texts.map((text, i) => ({ id: String.fromCharCode(97 + i), text })), sources: refs(...keys) };
}
